from collections import Counter


def transform(grid):
    """Overlay two panels, marking positions where both contain their shared symbol."""
    h, w = len(grid), len(grid[0])
    if w % 2 == 1:
        c = w // 2
        if len({grid[r][c] for r in range(h)}) == 1:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
        else:
            a = b = None
    else:
        a = b = None
    if a is None and h % 2 == 1:
        r = h // 2
        if len(set(grid[r])) == 1:
            a, b = grid[:r], grid[r + 1:]
    if a is None:
        raise ValueError('No centered full separator found')
    if len(a) != len(b) or any(len(x) != len(y) for x, y in zip(a, b)):
        raise ValueError('Panels differ in size')
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    if len(shared) != 1:
        raise ValueError(f'Expected one shared color, found {shared}')
    color = next(iter(shared))
    return [[3 if x == color and y == color else color for x, y in zip(ra, rb)]
            for ra, rb in zip(a, b)]
